						RealType mi3ezoom = max({ mi3eds.Real(X_), mi3eds.Real(Y_), mi3eds.Real(Z_) }) + IntType(16);
						VecType mi3eoff = point3D_mul(point3D_add(idVec(ObjType(obj_template, mi3etemp)->model_file, bounds_parts_start), vec3_mul(mi3eds, 0.5)), -IntType(1));
						VecType mi3epf = global::proj_from;
						global::proj_from = point3D(lengthdir_x(mi3ezoom, self->xyangle) * lengthdir_x(1.0, self->zangle), lengthdir_y(mi3ezoom, self->xyangle) * lengthdir_x(1.0, self->zangle), lengthdir_z(mi3ezoom, self->zangle));
						global::render_ratio = IntType(1);
						gpu_set_ztestenable(true);
						camera_apply(global::cam_render);
